1	@import "tailwindcss" source(none);
2	/* Scan ONLY the design system's own src/ so the CSS includes every utility the components use. source(none) stops Tailwind's automatic detection from pulling class-like words out of docs, skills and README text into the shipped CSS. Stories are scanned here because Storybook compiles this file; the shipped dist/styles.css is compiled from build.css, which leaves story-only utilities out. */
3	@source "../**/*.{js,ts,jsx,tsx}";
4	@import "./tokens.css";
5	@import "./dooph-component-tokens.css";
6	
7	/*
8	 * Toggle Option selection state. Tabs (Radix Tabs) mark the chosen option
9	 * data-state=active; toggle groups (Radix ToggleGroup) mark it data-state=on.
10	 * One variant pair lets the shared toggleOptionVariants recipe serve both.
11	 */
12	@custom-variant selected (&:is([data-state="active"], [data-state="on"]));
13	@custom-variant unselected (&:not([data-state="active"], [data-state="on"]));
14	@plugin "tailwindcss-animate";
15	
16	/*
17	 * SidebarWithHoverIcon rail — the two scalars the icon's path is a function of.
18	 * Registered so they INTERPOLATE: an unregistered custom property is a token
19	 * string and jumps between values, which is the whole reason these exist.
20	 *
21	 *   --ds-sidebar-rail-s  side.  0 = left, 1 = right.
22	 *   --ds-sidebar-rail-h  hover. 0 = straight rail, 1 = chevron.
23	 *
24	 * CSS owns the motion and the component owns only the geometry: it sets the two
25	 * targets as inline style and samples the interpolated values each frame to
26	 * write `d` (SVG path data is not itself animatable in every engine). So
27	 * duration and easing come from the motion scale and reduced motion from its
28	 * global block, all retunable by a consumer, with no numbers mirrored into
29	 * JavaScript to drift out of step.
30	 */
31	@property --ds-sidebar-rail-s {
32	  syntax: "<number>";
33	  inherits: false;
34	  initial-value: 0;
35	}
36	@property --ds-sidebar-rail-h {
37	  syntax: "<number>";
38	  inherits: false;
39	  initial-value: 0;
40	}
41	
42	/* MorphRotationShape. `step` is the transitioned value the component samples:
43	 * integer part = stop, fraction = morph progress; the spring ease overshoots,
44	 * so it runs past each stop. `clock` only exists so autoplay has an animation
45	 * whose iterations mark each step. */
46	@property --ds-shape-morph-step {
47	  syntax: "<number>";
48	  inherits: false;
49	  initial-value: 0;
50	}
51	@property --ds-shape-morph-clock {
52	  syntax: "<number>";
53	  inherits: false;
54	  initial-value: 0;
55	}
56	@property --ds-shape-morph-lean {
57	  syntax: "<number>";
58	  inherits: false;
59	  initial-value: 0;
60	}
61	
62	/* LoadingSpinner (flat) — Material's circular indeterminate dash, as two
63	 * numbers animated on the <svg> once per --ui-spinner-duration:
64	 *   --ds-spinner-grow  0 → 1 → 1   the arc's length, min → max sweep
65	 *   --ds-spinner-tail  0 → .118 → .985  where the arc's tail sits, in turns
66	 * Both arc paths compute their dashes from the same two values, so the arc
67	 * and the track cannot drift apart. Registered so the animation interpolates
68	 * numbers; inherited so the paths read the values animated on their <svg>. */
69	@property --ds-spinner-grow {
70	  syntax: "<number>";
71	  inherits: true;
72	  initial-value: 0;
73	}
74	@property --ds-spinner-tail {
75	  syntax: "<number>";
76	  inherits: true;
77	  initial-value: 0;
78	}
