134	const NUMBER_PATTERN = /^-?\d+(\.\d+)?$/;
135	const WHITESPACE = /[\s  ]/g;
136	const escapeRegExp = (text: string) =>
137	  text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
138	
139	const DEFAULT_SEPARATORS: NumberSeparators = { group: ",", decimal: "." };
