  font-style: normal;
  font-weight: var(--ui-weight-button);
  font-variation-settings: var(--ui-font-var-button);
}

/* Mono deliberately mirrors button's size and weight (both tokens alias it)
 * so a mono run set beside a button label sits at the same optical scale.
 * The MONO axis is named explicitly — see the token's note on why trusting
 * the family default is not enough. */
.text-style-mono {
  font-family: var(--ui-font-mono);
  font-optical-sizing: auto;
  font-size: var(--ui-text-mono);
  font-style: normal;
  font-weight: var(--ui-weight-mono);
  font-variation-settings: var(--ui-font-var-mono);
  letter-spacing: var(--ui-tracking-mono);
}

.text-style-label {
  font-family: var(--ui-font-label);
  font-size: var(--ui-text-label);
  font-weight: var(--ui-weight-label);
  letter-spacing: var(--ui-tracking-label);
}

.text-style-title {
