import { useState } from "react";
import type { Meta, StoryObj } from "@storybook/react-vite";
import { CheckboxField } from "./CheckboxField";
import {
  CheckboxChecked,
  CheckboxVariant,
  type CheckboxChecked as CheckboxCheckedValue,
} from "../Checkbox/constants";

const meta = {
  title: "Inputs/CheckboxField",
  component: CheckboxField,
  parameters: { layout: "centered" },
  tags: ["autodocs"],
  argTypes: {
    variant: {
      control: "select",
      options: Object.values(CheckboxVariant),
    },
  },
} satisfies Meta<typeof CheckboxField>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    label: "Accept terms and conditions",
  },
};

export const WithHint: Story = {
  args: {
    label: "Email notifications",
    hint: "Receive updates about your account activity via email.",
  },
};

export const Checked: Story = {
  args: {
    label: "Email notifications",
    hint: "Receive updates about your account activity via email.",
    checked: CheckboxChecked.checked,
  },
};

export const Primary: Story = {
  args: {
    label: "Email notifications",
    hint: "Receive updates about your account activity via email.",
    checked: CheckboxChecked.checked,
    variant: CheckboxVariant.primary,
  },
};

export const Disabled: Story = {
  args: {
    label: "Email notifications",
    hint: "Receive updates about your account activity via email.",
    checked: CheckboxChecked.checked,
    disabled: true,
  },
};

export const Controlled: Story = {
  render: function ControlledStory() {
    const [checked, setChecked] = useState<CheckboxCheckedValue>(
      CheckboxChecked.unchecked,
    );

    return (
      <CheckboxField
        label="Dark mode"
        hint="Use the dark colour scheme across the app."
        checked={checked}
        onCheckedChange={setChecked}
      />
    );
  },
};

export const AllStates: Story = {
  render: () => (
    <div className="flex flex-col gap-xl" style={{ width: 320 }}>
      <CheckboxField label="Unchecked" hint="No value selected yet." />
      <CheckboxField
        label="Checked"
        hint="This option is on."
        checked={CheckboxChecked.checked}
      />
      <CheckboxField
        label="Indeterminate"
        hint="A mixed state."
        checked={CheckboxChecked.indeterminate}
      />
      <CheckboxField
        label="Disabled unchecked"
        hint="Cannot be changed."
        disabled
      />
      <CheckboxField
        label="Disabled checked"
        hint="Locked on."
        checked={CheckboxChecked.checked}
        disabled
      />
      <CheckboxField label="Label only" />
    </div>
  ),
};

